begin;
update public.book_maps set metadata=jsonb_set(metadata,'{illustratedAtlas,geographicPlaces,regional-town}',(metadata#>'{illustratedAtlas,geographicPlaces,regional-town}')||convert_from(decode('','base64'),'UTF8')::jsonb) where book_id='macondo' and id='reading-map' and metadata#>>'{illustratedAtlas,geographicPlaces,regional-town,scope}'='real-literary-model';
commit;
select (select count(*) from jsonb_object_keys(metadata#>'{illustratedAtlas,geographicPlaces,regional-town,chapterRoles}')) from public.book_maps where book_id='macondo' and id='reading-map';
